DEMON_CATALOGS.lores = DEMON_CATALOGS.lores.map(entry => ({ ...entry, ...(DEMON_LORE_DETAILS[entry.key] ?? {}) }));

export function getDemonCatalogEntry(catalog, key) {
  return (DEMON_CATALOGS[catalog] ?? []).find(entry => entry.key === key) ?? null;
}
